TSV = '/Volumes/aro/projects/prose_generation/enrichment/bible/work/s103/discovery/s103-20261009/103_1.merged.tsv'

ann = {}
for line in open(CALL + '/annotations.jsonl', encoding='utf-8'):
    if line.strip():
        r = json.loads(line)
        ann[r['id']] = r

def srcs(aid):
    return [s for s in ann[aid]['kaynak'].split('|') if s != 'hafiza']

A = lambda k: 'S103-' + k

# ---- judgement table (my decisions): ref -> (status, reason, paragraphs, evidence, [annotation ids])
# A = accepted, R = rejected, U = unavailable, Q = unresolved
J = {}
def acc(ref, aids, paras, reason, ev=None):
    J[ref] = ('accepted', reason, paras, ev or [ref], [A(a) for a in aids])
def rej(ref, reason, paras=None, ev=None, aids=None):
    J[ref] = ('rejected', reason, paras or [], ev if ev is not None else [ref], [A(a) for a in (aids or [])])
def una(ref, reason):
    J[ref] = ('unavailable', reason, [], [], [])
def unr(ref, reason, aids=None):
    J[ref] = ('unresolved', reason, [], [], [A(a) for a in (aids or [])])

