rows = list(csv.DictReader(open(TSV, encoding='utf-8'), delimiter='\t'))
out = []
seen = set()
problems = []
for r in rows:
    ev = json.loads(r['evidence'])
    for e in ev:
        cid = e['connection_id']
        if cid in seen:
            continue
        seen.add(cid)
        ref = r['ref']
        if cid in OV:
            st, reason, paras, evd, aids = OV[cid]
            if evd is None:
                evd = J[ref][3] if ref in J else [ref]
        elif ref in J:
            st, reason, paras, evd, aids = J[ref]
        else:
            problems.append(('NO JUDGEMENT', cid, ref))
            continue
        if reason is None:
            problems.append(('NO REASON', cid, ref))
        evid = list(evd)
        paras = list(paras)
        for a in aids:
            for s in srcs(a):
                if s not in evid:
                    evid.append(s)
            if ann[a]['paragraf'] not in paras:
                paras.append(ann[a]['paragraf'])
        out.append({'connection_id': cid, 'ref': ref, 'status': st, 'reason': reason, 'paragraphs': paras, 'evidence': evid, 'annotations': aids})
for ref, st, reason, paras, aids, ev in R:
    aids = [A(a) for a in aids]
    evid = list(ev) if ev is not None else [ref]
    for a in aids:
        for s in srcs(a):
            if s not in evid:
                evid.append(s)
    out.append({'connection_id': None, 'origin': 'research', 'ref': ref, 'status': st, 'reason': reason, 'paragraphs': paras, 'evidence': evid, 'annotations': aids})

